"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["9189"],{47538(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.configuracao_distribuicao_vagas.modalidade_nao_encontrada","status":422,"titulo":"Modalidade n\xe3o encontrada ou n\xe3o est\xe1 mais viva"},"descricao":{"codigo":"uniplus.selecao.configuracao_distribuicao_vagas.modalidade_nao_encontrada","requisitos":[],"oQueAconteceu":["Um dos `modalidadeIds` de uma distribui\xe7\xe3o de vagas do corpo do pedido n\xe3o existe no\\ncat\xe1logo de modalidades de Configura\xe7\xe3o, ou existe mas n\xe3o est\xe1 mais viva.\\nEsta consulta \xe9 a que resolve, para cada modalidade selecionada, os campos\\nque este cat\xe1logo documenta como vindos do cadastro \u2014 `codigo`,\\n`naturezaLegal`, `composicaoVagas`, `baseLegal`, e a coer\xeancia de\\ncomposi\xe7\xe3o/remanejamento (ver\\n[`modalidade_selecionada.codigo_obrigatorio`](/erros/uniplus.selecao.modalidade_selecionada.codigo_obrigatorio)).\\nSem essa resolu\xe7\xe3o bem-sucedida, nenhum desses campos existe para conferir.","O processamento \xe9 sequencial: a **primeira** modalidade do array\\n`modalidadeIds` cuja resolu\xe7\xe3o falhar interrompe a passada \u2014 as modalidades\\nseguintes do mesmo array, e as distribui\xe7\xf5es seguintes do mesmo corpo do pedido, n\xe3o\\nchegam a ser conferidas."],"comoResolver":["Confirme, no cat\xe1logo de modalidades de Configura\xe7\xe3o, que cada `Id`\\ndeclarado em `modalidadeIds` existe e est\xe1 ativo. Se uma modalidade foi\\ndesativada recentemente, ou o `Id` est\xe1 incorreto, corrija o corpo do pedido antes\\nde reenviar.","Como o processamento para na primeira modalidade com problema, corrigir\\nesta e reenviar pode revelar uma nova falha numa modalidade seguinte do\\nmesmo corpo do pedido \u2014 n\xe3o \xe9 garantia de que o restante do corpo do pedido est\xe1 correto."],"ondeAparece":["Defini\xe7\xe3o de distribui\xe7\xe3o de vagas do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Configuracao distribuicao vagas"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"bac0ecb24f352b6341ba53a00922b6237dd7a678"}}')}}]);